    lines.length > 0 &&
    lines[0].toLowerCase().includes("zip")
      ? 1
      : 0;

  const currentCount = await db.zipCode.count({ where: { shop } });
  let imported = 0;
  let skipped = 0;
  const errors: string[] = [];

  for (let i = startIdx; i < lines.length; i++) {
    const cols = parseCsvRow(lines[i]);
