    const eta = cols[4] || null;
    const codRaw = (cols[5] || "").toLowerCase().trim();
    const codAvailable =
      codRaw === "yes" || codRaw === "true"
        ? true
        : codRaw === "no" || codRaw === "false"
          ? false
          : null;
    const returnPolicy = cols[6] || null;

