                      </IndexTable.Cell>
                      <IndexTable.Cell>
                        {z.message || (
                          <Text as="span" tone="subdued">
                            —
                          </Text>
                        )}
                      </IndexTable.Cell>
                      <IndexTable.Cell>
                        {z.eta || (
                          <Text as="span" tone="subdued">
                            —
                          </Text>
                        )}
                      </IndexTable.Cell>
                      <IndexTable.Cell>
                        {z.codAvailable === true ? (
