                            />
                          </Tooltip>
                        </InlineStack>
                      </IndexTable.Cell>
                    </IndexTable.Row>
                  ))}
                </IndexTable>
              </>
            )}
          </Card>
        </Layout.Section>
      </Layout>
      </Box>

      {/* Add Zip Code Modal */}
      <Modal
        open={addModalOpen}
        onClose={() => {
          setAddModalOpen(false);
          setNewZip("");
          setNewLabel("");
          setNewZone("");
          setNewMessage("");
          setNewEta("");
          setNewType("allowed");
          setNewCodAvailable("");
          setNewReturnPolicy("");
        }}
        title="Add Zip Code"
        primaryAction={{
          content: "Add Zip Code",
          onAction: handleAdd,
          loading: isAddLoading,
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => {
