                ) : (
                  <Text as="p">
                    Imported <strong>{rangeResult.imported as number}</strong> zip codes
                    ({rangeResult.total as number} in range).
                  </Text>
                )}
              </Banner>
            )}
            <Text as="p" variant="bodyMd">
              Enter a numeric ZIP code range to bulk-import up to 500 zip codes at once.
              Only 5-digit US ZIP codes are supported.
            </Text>
            <InlineGrid columns={2} gap="300">
              <TextField
                label="Start ZIP"
                value={rangeStart}
                onChange={setRangeStart}
                placeholder="10001"
                autoComplete="off"
                maxLength={5}
              />
              <TextField
                label="End ZIP"
                value={rangeEnd}
                onChange={setRangeEnd}
                placeholder="10099"
                autoComplete="off"
                maxLength={5}
              />
            </InlineGrid>
            <Select
              label="Status"
              options={typeOptions}
              value={rangeType}
              onChange={setRangeType}
            />
            <TextField
              label="Zone (optional)"
              value={rangeZone}
              onChange={setRangeZone}
              placeholder="Manhattan"
              autoComplete="off"
              helpText="Group these ZIP codes under a zone name."
            />
            <TextField
              label="Delivery Message (optional)"
              value={rangeMessage}
              onChange={setRangeMessage}
              placeholder="We deliver to your area!"
              autoComplete="off"
            />
            <TextField
              label="ETA (optional)"
              value={rangeEta}
              onChange={setRangeEta}
              placeholder="2-3 business days"
              autoComplete="off"
            />
          </BlockStack>
        </Modal.Section>
      </Modal>

      {/* Bulk Delete Confirmation Modal */}
      <Modal
        open={confirmBulkDeleteOpen}
        onClose={() => setConfirmBulkDeleteOpen(false)}
        title={`Delete ${selectedIds.length} zip code${selectedIds.length !== 1 ? "s" : ""}?`}
        primaryAction={{
          content: "Delete",
          onAction: handleBulkDeleteConfirm,
          loading: isBulkDeleteLoading,
          destructive: true,
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => setConfirmBulkDeleteOpen(false),
          },
        ]}
      >
        <Modal.Section>
          <Text as="p">
            This will permanently delete{" "}
            <strong>
              {selectedIds.length} zip code{selectedIds.length !== 1 ? "s" : ""}
            </strong>
            . This action cannot be undone.
          </Text>
        </Modal.Section>
      </Modal>
    </Page>
  );
}

export function ErrorBoundary() {
  return boundary.error(useRouteError());
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

