 69→// 1. Waitlist Confirmation  (App → Customer)
 70→// ---------------------------------------------------------------------------
 71→
 72→export async function sendWaitlistConfirmation(
 73→  to: string,
 74→  zipCode: string,
 75→  shop: string,
 76→  options?: EmailOptions,
 77→): Promise<boolean> {
 78→  const resend = getClient();
 79→  if (!resend) return false;
 80→
 81→  const name = options?.senderName?.trim() || shopFallbackName(shop, options);
 82→
 83→  try {
 84→    await resend.emails.send({
 85→      from: buildFrom(shop, options),
 86→      to,
 87→      subject: `You're on the waitlist — ${name}`,
 88→      html: `
 89→        <div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;padding:24px">
 90→          <h2 style="margin:0 0 16px">You're on the waitlist!</h2>
 91→          <p>Thanks for signing up. We'll let you know as soon as delivery is available to <strong>${zipCode}</strong>.</p>
 92→          <p style="color:#666;font-size:13px;margin-top:24px">— ${name}</p>
 93→        </div>
 94→      `,
 95→      text: `You're on the waitlist!\n\nThanks for signing up. We'll let you know as soon as delivery is available to ${zipCode}.\n\n— ${name}`,
